"use client";

import HoloCard from "./reactbits/HoloCard";
import { useTheme } from "./useTheme";

/**
 * Holographic, flippable player card. Artwork lives in /public/card and is
 * generated by `npm run cards` (scripts/make-cards.mjs).
 */
export default function PlayerHoloCard() {
  const theme = useTheme();

  return (
    <div className="player-holo">
      <HoloCard
        image={`/card/front-${theme}.svg`}
        backImage={`/card/back-${theme}.svg`}
        alt="Prajjwal Patel player card: No. 24, full stack developer and researcher at KIIT. Press to flip for the player profile."
        preset="rainbow"
        intensity={theme === "dark" ? 0.14 : 0.18}
        edgeSparkle={0.2}
        frame={3}
        glare={0.3}
        foilColor={theme === "dark" ? "#e5e5e5" : "#cfe0ff"}
        width={340}
        radius={18}
        tiltMax={14}
        style={{ ["--hc-w" as string]: "min(340px, 100%)" }}
      />
      <span className="player-holo-hint">Tap or click the card to flip</span>
    </div>
  );
}
